-- Template da casa "Desliza IA" (as camadas vivem no código, o banco guarda nome, paleta e ordem).
insert into public.templates (id, name, description, description_en, category, layout, palette, fonts, supports_ai_cover, sort_order) values
  ('desliza', 'Desliza IA', 'O template da casa: foto de fundo em fade pro preto, número do card, manchete grande em Sora com a palavra-chave em cor, seta pra deslizar. Curiosidade, tecnologia, negócios, história. Palavras entre **asteriscos** ganham cor.', 'The house template: photo fading to black, card number, big Sora headline with the key word in color, swipe arrow. **Words** in asterisks get the accent color.', 'geral', 'niche', '{"bg":"#0b0b0f","fg":"#f8fafc","accent":"#a3e635","muted":"#c4c4cc","accent2":"#7c3aed"}', '{"display":"Sora","body":"Inter"}', true, 0)
on conflict (id) do update set name = excluded.name, description = excluded.description, description_en = excluded.description_en, palette = excluded.palette, fonts = excluded.fonts, sort_order = excluded.sort_order, active = true;
